class Solution {
public:
    int countOfArrays(int n, int m, int k) {
        const long long MOD = 1000000007;
        long long even = m / 2;
        long long odd = m - even;

        vector<vector<long long>> dp(k + 1, vector<long long>(2, 0));
        dp[0][0] = even;
        dp[0][1] = odd;

        for (int step = 2; step <= n; ++step) {
            vector<vector<long long>> new_dp(k + 1, vector<long long>(2, 0));
            for (int j = 0; j <= k; ++j) {
                long long from_even = (j > 0 ? dp[j - 1][0] : 0);
                long long from_odd = dp[j][1];
                new_dp[j][0] = ((from_even + from_odd) * even) % MOD;
                new_dp[j][1] = ((dp[j][0] + dp[j][1]) * odd) % MOD;
            }
            dp = std::move(new_dp);
        }
        return (dp[k][0] + dp[k][1]) % MOD;
    }
};

