        long even = m / 2;
        long odd = m - even;

        long[][] dp = new long[k + 1][2];
        dp[0][0] = even;
        dp[0][1] = odd;

        for (int step = 2; step <= n; step++) {
            long[][] newDp = new long[k + 1][2];
            for (int j = 0; j <= k; j++) {
                long fromEven = (j > 0 ? dp[j - 1][0] : 0);
                long fromOdd = dp[j][1];
                newDp[j][0] = ((fromEven + fromOdd) * even) % MOD;
                newDp[j][1] = ((dp[j][0] + dp[j][1]) * odd) % MOD;
            }
            dp = newDp;
        }
        return (int) ((dp[k][0] + dp[k][1]) % MOD);
    }
}

